import json, re
exec(open('build2.py').read().split('\nP = {}\n')[0])
DRY="<h3>Care</h3><p>Wipe with a soft dry cloth and keep it out of heavy rain. If it gets stained, clean it gently as soon as you can; for deep cleaning, use a professional leather cleaner. Do not wash, bleach, iron or tumble dry. Condition the leather every few months and stuff the bag lightly when stored so it keeps its shape.</p>"
P={}
P["the-forester-backpack-duffle-bag"]=(DRY,"<p>One bag, three ways to carry it. The Forester is a leather travel duffle that switches between a top-handle duffle, a hands-free backpack and a cross-body sling, so it works for a weekend away, a business trip, the gym or a day outdoors.</p><h3>Three carry modes</h3>"+ul(["Top-handle mode: classic duffle carry for a smart look","Backpack mode: adjustable straps for hands-free long hauls","Cross-body sling mode: quick access on the move"])+"<h3>Details</h3>"+ul(["Genuine leather","Spacious main compartment with a slim profile","Colours: Brown, Crazy Horse, Tan and Black"])+"<h3>Who it is for</h3><p>For travellers, gym-goers and professionals who want one bag instead of three, and a strong gift for a man who travels.</p>",[("Is it cabin size?","Message us on WhatsApp with your airline and we will send the exact measurements."),("Which colour ages best?","Crazy Horse and Tan show the most patina over time; Black stays the most uniform.")])
P["tp-venture-pack"]=(CARE['smooth'],"<p>The Venture Pack is a full-grain leather cross-body bag for everyday carry. It keeps your phone, wallet, keys, a small notebook and a power bank organised and close at hand, whether you are commuting, travelling or out in the city.</p><h3>What it carries</h3>"+ul(["Multiple compartments for phone, wallet, keys, notebook and power bank","Zipped compartments for security and quick access","Adjustable strap: wear it over the shoulder or across the chest","100% full-grain leather that ages beautifully","Colours: Black, Brown and Tan"])+"<h3>Who it is for</h3><p>For men who want their hands free and their essentials secure, from the office to the bazaar to the airport.</p>",[("Will a phone fit in the front?","Yes. It is made to carry a phone, wallet and keys together; for very large phones, message us your model on WhatsApp.")])
P["the-traveler-multi-function-crazy-horse-leather-duffle-bag"]=(DRY,"<p>The Traveler is a multi-function duffle in top-grain Crazy Horse cow leather that opens completely flat, with dedicated places for a suit, shoes, ties and essentials, so you arrive organised and crease-free.</p><h3>What it carries</h3>"+ul(["Suit compartment that keeps formalwear neatly packed","Separate shoe pocket, away from clothing","Tie and accessory pockets for belts, ties and watches","Utility pockets for tech, documents and small travel items","Opens flat for easy packing and unpacking","Sturdy top handles and a long, adjustable shoulder strap"])+"<h3>Who it is for</h3><p>For business trips, weddings and weekends away, when a suit has to arrive looking like a suit.</p>",[("Does the suit really stay crease-free?","The suit compartment holds it flat and separate, which keeps creasing to a minimum on most trips.")])
P["gridle-crossbody"]=(CARE['smooth'],"<p>The Gridle is a vintage-style cross-body bag in vegetable-tanned full-grain leather. Vegetable tanning gives the leather a firm, natural feel that develops a rich honey patina over time, so the bag becomes more yours the longer you carry it.</p><h3>What it carries</h3>"+ul(["Spacious main compartment for daily essentials","Secure buckle-flap closure","Adjustable shoulder strap","100% vegetable-tanned full-grain leather"])+"<h3>Who it is for</h3><p>For city days, travel and the office, and for anyone who loves leather that ages with character.</p>",[("What is vegetable-tanned leather?","Leather tanned with natural plant tannins. It starts firmer and lighter, then darkens and softens into a patina with use.")])
P["the-saloon-laptop-bag"]=(CARE['smooth'],"<p>The Saloon is a vintage-inspired laptop bag in full-grain leather, hand-stitched and finished with brass buckles. It carries a 15.6-inch laptop and the working day around it, and develops a rich patina over time.</p><h3>What it carries</h3>"+ul(["Padded laptop compartment for laptops up to 15.6 inches","Multiple compartments for documents, chargers and essentials","Brass buckles and zips","Adjustable shoulder strap: carry it on the shoulder or cross-body","Full-grain leather, hand-stitched"])+"<h3>Who it is for</h3><p>For professionals who want a laptop bag with character for the office and travel, and a memorable gift for entrepreneurs and leather lovers.</p>",[("Will a 15.6-inch laptop fit?","Yes. The padded compartment is made for laptops up to 15.6 inches.")])
P["zulfiqar-laptop-bag"]=(CARE['smooth'],"<p>The Zulfiqar is a laptop messenger bag in full-grain vegetable-tanned leather, with room for a laptop up to 16 inches plus documents, chargers and essentials. It develops a rich patina with use, so it looks better every year.</p><h3>What it carries</h3>"+ul(["Padded sleeve for laptops up to 16 inches","Dedicated sections for accessories","Secure zipped pockets","Brass hardware and YKK zips","Adjustable, detachable leather shoulder strap plus carry handles"])+"<h3>Who it is for</h3><p>For executives, creatives and anyone who carries a large laptop, from meetings to travel. Natural leather, so shades vary slightly from bag to bag.</p>",[("Will a 16-inch laptop fit?","Yes. The padded sleeve takes laptops up to 16 inches.")])
P["hilford-backpack"]=(DRY,"<p>The Hilford is a rugged, distressed dark brown leather backpack in cowhide, with buckle closures and a satin-lined interior. It is made for daily commutes, travel and weekends, and wears in with real character.</p><h3>What it carries</h3>"+ul(["Main compartment with a dual buckle strap and drawstring closure","Two side zip pockets","Front pocket with a flap cover","Adjustable shoulder straps with buckles","Satin lining","Distressed cowhide leather in dark brown"])+"<h3>Who it is for</h3><p>For men who want a leather backpack with a vintage, rugged look for the office, travel and casual days.</p>",[("Will a laptop fit?","Send us your laptop size on WhatsApp and we will confirm before you order.")])
P["rl-the-hilford-backpack"]=(CARE['smooth'],"<p>The Rastov is a top-grain cow leather backpack with a flap closure, buckle details and a drawstring, made for the commute, campus and weekend. The leather ages into a unique patina over time.</p><h3>What it carries</h3>"+ul(["Spacious main compartment with flap and buckle closure","Drawstring inner closure","Internal pockets for organisation","Room for daily essentials and documents","Adjustable, comfortable shoulder straps","Colours: Red, Bodo and Maroon"])+"<h3>Who it is for</h3><p>For students and professionals who want a leather backpack in a colour that stands out.</p>",[("Will my laptop fit?","Send us your laptop size on WhatsApp and we will confirm before you order.")])
P["bl-textured-backpack-black"]=(CARE['smooth'],"<p>A black leather backpack with a bold textured surface, a dual-tone finish and brass accents: rugged enough for daily use and smart enough for the office.</p><h3>What it carries</h3>"+ul(["Multi-compartment design with zips and buckles","Reinforced shoulder straps for all-day comfort","Genuine leather with a textured surface","Brass accents","Colour: Black"])+"<h3>Who it is for</h3><p>For work, travel and anyone who wants a backpack that stands out from plain black bags.</p>",[("Will a laptop fit?","Send us your laptop size on WhatsApp and we will confirm before you order.")])
out={}
for h,(care,body,qs) in P.items():
    html=body+care+faq(qs)+STD
    txt=re.sub("<[^>]+>"," ",html).lower()
    for bad in ["coin","karachi","workshop","hand-cut","order now","top-selling","ethically","#","✅","🔹","hilford" if h=="rl-the-hilford-backpack" else "zzzz"]:
        assert bad not in txt,(h,bad)
    out[h]={"html":html,"words":len(txt.split())}
json.dump(out,open('batch5.json','w'),indent=1)
for h,v in out.items(): print(v['words'],h)
